import type { QuestionTranslation } from '../types/question';

// RU explanation overlays, keyed by question id.
// AUTO-GENERATED by scripts/translate-explanations.ts — do not edit by hand.
export const explanationsRu: Record<string, QuestionTranslation> = {
  "nia-01-001": { explanation: "Телекоммуникационный кабель для помещений в обычном здании обычно имеет класс Cca-s1b,d2,a2. Основная буква (Cca) описывает распространение пламени; подбуквы s, d и a описывают образование дыма, горящих капель и кислотность." },
  "nia-01-002": { explanation: "Цифра \"s\" в обозначении Еврокласса указывает на образование дыма. s1a - это самый низкий уровень дыма, поэтому B2ca s1a d1 a1 производит меньше дыма, чем альтернативные варианты s1b или s2." },
  "nia-01-003": { explanation: "Кабели для передачи данных, телефонные кабели и кабели охранной сигнализации относятся к кабелям связи. Сетевой кабель 230 В является низковольтным силовым кабелем и относится к электроустановкам, а не к телекоммуникациям." },
  "nia-01-004": { explanation: "При наружной прокладке кабель подвергается воздействию ультрафиолетовых лучей и погодных условий. Материал оболочки и номинал, а не только категория данных, определяют пригодность кабеля. BS EN 50174-3 описывает требования к внешнему монтажу." },
  "nia-01-005": { explanation: "Постоянный канал класса EA ограничен 90 м. Цифра 100 м - это общая длина канала, включающая постоянный канал плюс оборудование и коммутационные шнуры." },
  "nia-01-006": { explanation: "Канал - это постоянное звено плюс шнуры на каждом конце. Для класса EA общая длина канала составляет 100 м, оставляя 10 м для шнуров над постоянным звеном длиной 90 м." },
  "nia-01-007": { explanation: "Если общая длина шнура превышает 20 м, запас канала для фиксированного кабеля уменьшается до 95 м, чтобы вносимые потери не выходили за рамки класса EA." },
  "nia-01-008": { explanation: "Для небольших шкафов (≤21U) требуется защитный проводник сечением не менее 4 мм² согласно HD 60364-5-54. Для более крупных шкафов требуется проводник сечением 16 мм²." },
  "nia-01-009": { explanation: "Для больших стоек (>21U) стандарт HD 60364-5-54 предписывает использовать как минимум 16 мм² проводника. Этот же стандарт лежит в основе правил заземления и связывания BS 7671." },
  "nia-01-010": { explanation: "Настенный шкаф 12U относится к классу малых шкафов (≤21U), поэтому минимальный проводник связи 4 мм² применяется независимо от материала двери." },
  "nia-01-011": { explanation: "100baseT работает по сбалансированной витой паре, например Cat5e. 100baseSX - оптический, а 10base2 и 10base5 - устаревшие варианты коаксиального Ethernet." },
  "nia-01-012": { explanation: "Сбалансированные медные категории, такие как Cat 6A, Cat 7 или Cat 8, ограничены расстоянием около 100 м при скорости 10 Гбит/с. На расстоянии 500 м оптоволокно является правильным семейством носителей." },
  "nia-01-013": { explanation: "Многомодовые волокна предназначены для коротких линий связи, обычно несколько сотен метров при скорости 10 Гбит/с. Для километровых линий связи со скоростью 10 Гбит/с используется одномодовое волокно." },
  "nia-01-014": { explanation: "9/125 мкм - одномодовый; 50/125 мкм и 62,5/125 мкм - многомодовый. 100/125 не является признанным стандартным размером для телекоммуникационного волокна." },
  "nia-01-015": { explanation: "CPR относится к Положению о строительной продукции, которое устанавливает рамки для декларирования характеристик строительной продукции, включая характеристики реакции на огонь для кабелей." },
  "nia-01-016": { explanation: "Декларация о характеристиках - это документ, в котором производитель указывает заявленные характеристики строительного изделия, включая оценку по классу реакции на огонь EuroClass." },
  "nia-01-017": { explanation: "Маркировка CE - это знак соответствия соответствующим директивам или нормам ЕС, применимым к данному классу продукции. Он не является заявлением о происхождении и не является всемирным одобрением." },
  "nia-02-001": { explanation: "В BS EN 50174-2 для 4-парных сбалансированных кабелей в качестве ориентира по радиусу изгиба используется 8× наружного диаметра. Более тугие изгибы влияют на перекрестные помехи и обратные потери." },
  "nia-02-002": { explanation: "Для оптоволокна и коаксиального кабеля в BS EN 50174-2 в качестве эталонного радиуса изгиба используется 10× наружного диаметра кабеля. Значения производителей могут быть более жесткими для кратковременного вытягивания, но установленные изгибы должны соответствовать стандарту." },
  "nia-02-003": { explanation: "высота 1U в 19-дюймовой стойке составляет 44,45 мм (1,75 дюйма). Оборудование, монтируемое в стойку, имеет размеры в целых единицах стойки (1U, 2U, 4U и т. д.)." },
  "nia-02-004": { explanation: "Система управления кабелями охватывает весь спектр изделий, предназначенных для размещения или поддержки кабелей, включая каналы и трубки для прокладки под давлением. Транспортная упаковка не является системой управления." },
  "nia-02-005": { explanation: "Решетки подвесных потолков не рассчитаны на нагрузку от кабельных трасс. Конструкция должна быть закреплена на самой конструкции, чтобы потолочная решетка несла только свой собственный вес." },
  "nia-02-006": { explanation: "Добавление кабелей увеличивает вес и может превысить расчетную нагрузку на защитную оболочку и ее крепления. Нагрузка должна быть проверена перед протаскиванием дополнительных кабелей." },
  "nia-02-007": { explanation: "К путям эвакуации предъявляются особые требования пожарной безопасности. Конструкция, крепления и любые уплотнения должны быть подобраны таким образом, чтобы маршрут оставался безопасным во время эвакуации или пожара." },
  "nia-02-008": { explanation: "Зажатый или раздавленный кабель может не выдержать эксплуатационных испытаний и со временем повредиться. Крышки должны закрываться плотно, без давления на кабели." },
  "nia-02-009": { explanation: "Совместное размещение должно учитывать электрическое разделение, соображения электромагнитной совместимости, идентификацию и политику клиента. Маршрут должен управляться таким образом, чтобы одна услуга не нарушала другую." },
  "nia-02-010": { explanation: "Изгибы в защитной оболочке не должны заставлять кабели опускаться ниже допустимого радиуса изгиба. Поставляемые производителем аксессуары для изгибов предназначены для поддержания такой геометрии." },
  "nia-02-011": { explanation: "Вырезанные на площадке защитные оболочки могут оставлять острые заусенцы, которые истирают или режут оболочки кабелей при прокладке и последующем перемещении. Заусенцы следует удалить или закрыть специальной втулкой." },
  "nia-02-012": { explanation: "Контейнер безопасен лишь настолько, насколько надежны его крепления и фон. Основание, нагрузка и окружающая среда влияют на правильное крепление." },
  "nia-02-013": { explanation: "Слишком тугие стяжки могут раздавить сбалансированный кабель и ухудшить характеристики передачи. Ограничители должны удерживать пучок без изменения геометрии кабеля." },
  "nia-02-014": { explanation: "Маршруты прокладки сетевых кабелей должны оставаться проверяемыми и обслуживаемыми. Контейнеры должны быть установлены таким образом, чтобы крышки, стыки и точки доступа были доступны." },
  "nia-02-015": { explanation: "Влажность и химическая среда сокращают срок службы неподходящей защитной оболочки и могут со временем ослабить опору. Класс защитной оболочки и крепежа следует выбирать с учетом условий окружающей среды." },
  "nia-02-016": { explanation: "Деформационные швы существуют потому, что здание движется. Жесткая защитная оболочка в месте соединения со временем будет повреждена и может передать напряжение на кабели." },
  "nia-02-017": { explanation: "Металлические защитные оболочки могут нуждаться в защитном соединении в зависимости от конструкции и требований электробезопасности. Электрический проект диктует стратегию связывания." },
  "nia-02-018": { explanation: "Потолочные плитки и решетки не являются опорами для кабелей. Кабель над потолком должен прокладываться в соответствующем лотке, корзине или другом подходящем месте." },
  "nia-02-019": { explanation: "Корзинный лоток хорошо работает, когда кабель поддерживается равномерно. Острые точки давления, плотная укладка и сильное провисание - все это искажает геометрию кабеля." },
  "nia-02-020": { explanation: "Качество содержимого напрямую влияет на безопасность, ремонтопригодность и производительность соединения. Вышеперечисленные пункты являются общими дефектами, которые следует устранить до передачи оборудования." },
  "nia-03-001": { explanation: "При прокладке кабелей Cat 6A и экранированных UTP обычно используется радиус изгиба 4× внешнего диаметра. Установленное (в эксплуатации) значение может быть меньше, чем при протяжке." },
  "nia-03-002": { explanation: "Высокопроизводительные сбалансированные кабели более чувствительны к геометрии. Из четырех перечисленных категорий Cat 6A имеет наибольший радиус изгиба." },
  "nia-03-003": { explanation: "Для Cat 6A в 20-миллиметровом кабелепроводе пример - 2 кабеля. Заполнение всегда следует проверять с учетом внешнего диаметра кабеля, изгибов и длины тяги." },
  "nia-03-004": { explanation: "магистраль 50 мм × 50 мм обеспечивает аккуратный и доступный маршрут на высоте стола для небольшого пучка, например 12 кабелей Cat 6. Остальные либо слишком малы, либо слишком велики для данного места." },
  "nia-03-005": { explanation: "Управляемый пучок снижает трение и позволяет избежать перенапряжения отдельных кабелей. Перекрещенные или перекрученные кабели увеличивают натяжение и риск повреждения." },
  "nia-03-006": { explanation: "Несовместимые смазочные материалы могут химически воздействовать на оболочку кабеля или оставлять остатки, влияющие на последующую заделку. Правильным выбором является смазка, одобренная производителем." },
  "nia-03-007": { explanation: "Короткая сервисная петля позволяет завершить и переделать работу в будущем. Провисание должно соответствовать радиусу изгиба и не должно превышать допустимую длину." },
  "nia-03-008": { explanation: "Многие кабели становятся хрупкими ниже предельной температуры монтажа. Протягивание кабеля ниже этой температуры может привести к растрескиванию оболочки и повреждению проводников." },
  "nia-03-009": { explanation: "Сбалансированная кабельная система подавляет синфазные помехи, но не защищена от них. Адекватное разделение, экранирование и надлежащая изоляция снижают наведенные шумы." },
  "nia-03-010": { explanation: "Длинные вертикальные линии могут оказывать значительное давление на заделки, если они не поддерживаются. Промежуточные опоры предотвращают нагрузку на разъемы и проводники." },
  "nia-03-011": { explanation: "Неровные или слишком большие отверстия могут повредить оболочку кабеля. Втулка или втулка защищает кабель и помогает поддерживать пожарную безопасность, если это необходимо." },
  "nia-03-012": { explanation: "Пересечение под прямым углом минимизирует параллельное воздействие между кабелями. Длинные параллельные линии повышают уровень электромагнитной совместимости, даже если необходимо одно пересечение." },
  "nia-03-013": { explanation: "Слишком полный кабелепровод, слишком много изгибов или ограниченное количество точек втягивания могут привести к чрезмерному натяжению кабеля при прокладке. Эти факторы необходимо проверить перед протяжкой." },
  "nia-03-014": { explanation: "Существующие маршруты могут быть перегружены, повреждены, заблокированы или больше не подходят. Краткое обследование перед прокладкой новых кабелей позволяет избежать повреждения существующих коммуникаций." },
  "nia-03-015": { explanation: "Загрязнения на конце кабеля могут повлиять на последующую заделку и результаты испытаний. Колпачки или пакеты сохраняют концы чистыми до момента заделки." },
  "nia-03-016": { explanation: "Идентификация обоих концов перед заделкой предотвращает перекрестное соединение и экономит повторные работы при тестировании. Окончательная маркировка может быть нанесена при заделке." },
  "nia-03-017": { explanation: "Дробление изменяет геометрию кабеля и может вызвать повреждения, которые не видны снаружи. Даже кратковременные разрушения могут привести к сбоям при проведении эксплуатационных испытаний." },
  "nia-03-018": { explanation: "Запланированная последовательность делает процесс вытягивания более безопасным, уменьшает трение и предотвращает запутывание, которое может повредить пучок." },
  "nia-03-019": { explanation: "Претерминированные сборки поставляются готовыми к подключению. Поврежденные разъемы означают неисправность соединения, поэтому защита от вытягивания необходима." },
  "nia-03-020": { explanation: "Предварительный контроль позволяет выявить повреждения на ранней стадии, поэтому соединение не сертифицируется со скрытыми дефектами." },
  "nia-04-001": { explanation: "Чрезмерное раскручивание на заделке увеличивает перекрестные помехи и ухудшает характеристики NEXT/обратных потерь. Каждая категория кабелей имеет максимальное значение раскручивания, обычно очень короткое." },
  "nia-04-002": { explanation: "Для кабелей передачи данных предельное количество пучков составляет 24 кабеля. Более длинные пучки могут увеличить нагрев, интерференцию между пучками и натяжение." },
  "nia-04-003": { explanation: "Крючки и петли можно отсоединять и накладывать заново, не защемляя кабель. Нейлоновые стяжки, затянутые туго, рискуют деформировать сбалансированный кабель." },
  "nia-04-004": { explanation: "Прокладка коммутационных шнуров влияет на идентификацию, воздухообмен и надежность. Готовые шнуры не следует разрезать и повторно терминировать на месте." },
  "nia-04-005": { explanation: "Волокно более чувствительно к изгибу, чем медь. Катушки, воздуховоды и лотки для управления изгибами обеспечивают минимальный радиус изгиба без резких петель." },
  "nia-04-006": { explanation: "Различные носители имеют разные потребности в обращении. Раздельное вертикальное и горизонтальное управление для каждого типа обеспечивает удобство обслуживания установки." },
  "nia-04-007": { explanation: "Контуры обслуживания должны контролироваться таким образом, чтобы они не блокировали воздушный поток, не пересекали пределы радиуса изгиба и не создавали опасность для будущего обслуживания." },
  "nia-04-008": { explanation: "Последние несколько сантиметров кабеля все еще влияют на производительность сертифицированной линии связи. Защемление или перекручивание за пластиной может привести к провалу теста." },
  "nia-04-009": { explanation: "Управляющие шины снимают механическую нагрузку с разъемов и освобождают шнуры от вентиляционных путей оборудования." },
  "nia-04-010": { explanation: "Блокировка воздушного потока приводит к повышению температуры оборудования и снижению его надежности. Пучки кабелей не должны располагаться напротив впускных или выпускных решеток." },
  "nia-04-011": { explanation: "Опрятный вид установки невозможно поддерживать, если идентификация скрыта, подменена или уничтожена во время одевания." },
  "nia-04-012": { explanation: "Вытаскивание отдельных кабелей может привести к повреждению оболочки и нарушению существующих заделок. Пучок следует вскрыть и переложить должным образом." },
  "nia-04-013": { explanation: "Ограничитель, расположенный слишком близко к заделке, может вывести проводники из положения или вызвать напряжение на вводе. Небольшое смещение обеспечивает стабильность заделки." },
  "nia-04-014": { explanation: "Кабели более высокой категории по-прежнему нуждаются в правильной геометрии, сдерживании и идентификации. Прирост производительности быстро теряется, если нарушается дисциплина при одевании." },
  "nia-05-001": { explanation: "Система CPR / EuroClass - это система классификации строительных изделий, используемая для классификации реакции кабеля на огонь (EN 13501-6). Приказ о пожарной безопасности и строительные нормы находятся на более высоком уровне." },
  "nia-05-002": { explanation: "CPR - это Правила производства строительных изделий, которые устанавливают гармонизированные рамки для заявленных характеристик продукции, включая реакцию на огонь для кабелей." },
  "nia-05-003": { explanation: "Cca-s1b,d2,a2 - это код Еврокласса, обычно используемый для прокладки новых стационарных кабелей передачи данных. Aca - негорючий (редкость для телекоммуникаций), а Fca - самый низкий рейтинг." },
  "nia-05-004": { explanation: "Этикетка с маркировкой CE на упаковке является обязательным местом для классификации по Евроклассу. На веб-сайтах и в технических паспортах она тоже может быть указана, но этикетка - это контрольная ссылка." },
  "nia-05-005": { explanation: "Записи о противопожарных перекрытиях поддерживают стратегию пожарной безопасности здания и демонстрируют, что отсеки были правильно восстановлены." },
  "nia-05-006": { explanation: "Противопожарные характеристики основаны на проверенных системах. Непродуманные комбинации продуктов аннулируют результаты испытаний." },
  "nia-05-007": { explanation: "Даже небольшие зазоры обеспечивают распространение дыма и нарушают герметичность помещения. Для герметизации должна использоваться указанная система, а не подручные материалы." },
  "nia-05-008": { explanation: "Установленный кабель должен быть прослежен в соответствии с требованиями проекта по маркировке EuroClass на упаковке или оболочке, а также по прилагаемому DoP." },
  "nia-05-009": { explanation: "Защищенные шахты являются частью противопожарной стратегии здания. Кабельные работы не должны повреждать конструкцию шахты или ее отсеки." },
  "nia-05-010": { explanation: "Запрещается нарушать работу систем безопасности жизнедеятельности без соответствующего разрешения. Документированная процедура изоляции защищает жильцов здания и монтажника." },
  "nia-05-011": { explanation: "Неиспользуемые кабели увеличивают пожарную нагрузку и могут ввести в заблуждение будущих работников. Удаление или приведение в безопасное состояние должно соответствовать масштабу проекта и стратегии пожаротушения." },
  "nia-05-012": { explanation: "Замена крепежа может привести к аннулированию сертификата огнестойкости уплотнения. Система должна быть установлена в соответствии с испытаниями." },
  "nia-05-013": { explanation: "После закрытия маскировки недостающие или дефектные пломбы трудно и дорого найти и устранить. Проверка должна проводиться до закрытия." },
  "nia-05-014": { explanation: "Недостатки пожарной безопасности нельзя оставлять на неофициальное решение или скрывать при передаче. Формальный отчет помогает устранить недостатки и ведет аудиторский учет." },
  "nia-06-001": { explanation: "Управление барабаном - это отдельная задача, не связанная с протяжкой. Один человек контролирует скорость вращения барабана и его обгон; еще как минимум один человек управляет протяжкой." },
  "nia-06-002": { explanation: "Повреждения от трения обычно указывают на грубое или острое место в трассе. Продолжение движения приведет к повреждению большего количества кабеля, а повреждение оболочки может быть признаком более глубокого повреждения." },
  "nia-06-003": { explanation: "Сильно поврежденный барабан означает, что кабелю внутри него нельзя доверять. Барабан не должен использоваться для установки и сертификации." },
  "nia-06-004": { explanation: "Осколки представляют собой опасность травмирования и повреждения кабеля. Если опасность контролируется, барабан можно использовать, если сам кабель не поврежден." },
  "nia-06-005": { explanation: "Несовершенные опоры барабана небезопасны и могут разрушиться во время вытягивания. Правильная А-образная рама и шпиндель выдерживают вес барабана и обеспечивают контролируемое вращение." },
  "nia-06-006": { explanation: "Ручная обработка зависит от размера барабана, веса, маршрута, расстояния и конкретного человека. Решение принимается на основе оценки рисков, а не фиксированного числа." },
  "nia-06-007": { explanation: "Упавшие коробки создают опасность спотыкания и вытягивания, а также могут запутать кабель. Прежде чем продолжить работу, необходимо обеспечить безопасность рабочей зоны." },
  "nia-06-008": { explanation: "Два человека - это минимум: один подает коробку, другой тянет. Дополнительные люди добавляются, если препятствия на маршруте требуют дополнительного контроля." },
  "nia-06-009": { explanation: "Человек, находящийся в углу, уменьшает трение, контролирует радиус изгиба и держит движущийся кабель в поле зрения команды." },
  "nia-06-010": { explanation: "Специализированные инструменты для зачистки и резки снижают риск травм и повреждения кабеля. Ножи - это крайняя мера." },
  "nia-06-011": { explanation: "Три человека - это типичный минимум: один в будке, один подает маршрут и один на принимающей стороне." },
  "nia-06-012": { explanation: "Кабельные стержни предназначены для прокладывания через проходы и соединения по мере необходимости. Самодельные предметы могут повредить кабель или застрять в трассе." },
  "nia-06-013": { explanation: "Подозрительный асбест нельзя трогать без надлежащего обследования и контроля. Порядок действий на участке определяет дальнейшие шаги." },
  "nia-06-014": { explanation: "Арамидная нить быстро тупит обычные ножницы. Специализированные ножницы из кевлара режут чисто, не соскальзывая и не повреждая волокно." },
  "nia-06-015": { explanation: "Ножовочные полотна предназначены для пиления при прямом ходе. Установка их назад снижает эффективность реза и повышает риск поломки." },
  "nia-06-016": { explanation: "Бокорезы чисто обрезают медные проводники небольшого диаметра и оболочку кабеля. Ножовка или лобзик для этой работы не подходят." },
  "nia-06-017": { explanation: "Перманентный маркер с тонким наконечником выдерживает манипуляции во время вытягивания. Фетровый наконечник, шариковый и меловой маркеры слишком легко стираются." },
  "nia-06-018": { explanation: "Застежки с крючками и петлями можно отстегнуть и снова надеть без защемления троса, что делает их идеальными для одевания работ, которые еще могут быть отрегулированы." },
  "nia-06-019": { explanation: "Специальные стрипперы контролируют глубину реза и уменьшают повреждение внутренних пар и фольги. Ножи и ножницы легко режут слишком глубоко." },
  "nia-06-020": { explanation: "Проложенный кабель все еще может быть поврежден на объекте до передачи. Физическая защита и четкие указатели снижают этот риск." },
  "nia-07-001": { explanation: "Стандарт EN 420 устанавливает общие требования к защитным перчаткам. При этом важны соответствие размеру, ловкость рук и соответствие задаче." },
  "nia-07-002": { explanation: "СИЗ - это средства индивидуальной защиты. Оно является последней линией обороны и защищает пользователя." },
  "nia-07-003": { explanation: "Наклонная лестница должна быть установлена так, чтобы ее основание выходило на одну единицу высоты на каждые четыре единицы - примерно 75°." },
  "nia-07-004": { explanation: "Когда задействованы обе руки, для устойчивости все равно нужны три точки контакта. В качестве третьей точки может выступать корпус, колено или бедро." },
  "nia-07-005": { explanation: "Подозрительный асбест не должен быть потревожен. Территория должна контролироваться до тех пор, пока не начнется процедура работы с асбестом." },
  "nia-07-006": { explanation: "Пригодность СИЗ определяется оценкой рисков и условиями работы в данный день. Комфорт и бренд не являются критериями выбора." },
  "nia-07-007": { explanation: "На стройплощадке одновременно существует множество опасностей. Для протяжки кабеля обычно требуется полный комплект СИЗ." },
  "nia-07-008": { explanation: "BS EN 397 - это стандарт для промышленных защитных касок. Бренд и цвет являются организационными идентификаторами, а не показателями защиты." },
  "nia-07-009": { explanation: "Работодатели должны бесплатно предоставлять подходящие СИЗ, если оценка риска выявила необходимость в СИЗ." },
  "nia-07-010": { explanation: "Визуальный контроль перед использованием, проводимый пользователем, позволяет выявить очевидные дефекты в период между формальными проверками." },
  "nia-07-011": { explanation: "Отчетность о близких происшествиях - самый простой способ предотвратить повторные инциденты до того, как кто-то пострадает." },
  "nia-07-012": { explanation: "Шумовое воздействие может исходить от бурения, резки или близлежащих работ. Оценка уровня шума определяет требования." },
  "nia-07-013": { explanation: "Средства борьбы с пылью должны быть разработаны до начала работы. Иерархия такова: устранение, контроль у источника, затем СИЗ." },
  "nia-07-014": { explanation: "Оборудование для доступа должно быть в безопасном состоянии и соответствовать задаче и нагрузке." },
  "nia-07-015": { explanation: "Монтажники должны заботиться о безопасности других людей, а не только своей команды. Обычно требуется физическое разделение." },
  "nia-07-016": { explanation: "Некоторые продукты требуют использования перчаток, вентиляции, защиты глаз или специальной утилизации. В паспорте безопасности (SDS) перечислены средства контроля." },
  "nia-07-017": { explanation: "Быстрый доступ к первой помощи важен при порезах, травмах глаз или падениях. Вводный инструктаж на объекте должен охватывать эти меры." },
  "nia-07-018": { explanation: "Техническое задание остается действительным только до тех пор, пока фактические условия соответствуют плану. Значительные изменения требуют пересмотра." },
  "nia-07-019": { explanation: "Отвлечение на телефон - признанный фактор, способствующий спотыканиям, падениям и травмам от инструментов. Правила работы на объекте обычно ограничивают использование телефона определенными зонами." },
  "nia-07-020": { explanation: "Уборка по окончании работы предотвращает возникновение опасности для других работников и пользователей здания, которые придут сюда позже." },
  "nia-08-001": { explanation: "В тех случаях, когда данные об ИТ-кабеле неизвестны, руководство использует 200 мм в качестве консервативного минимального расстояния от силового кабеля." },
  "nia-08-002": { explanation: "Для этого сценария без разделения, с экранированной мощностью, максимальная длина составляет 35 м." },
  "nia-08-003": { explanation: "Для экранированной магистрали, расположенной рядом с неэкранированной силовой без разделителя, минимальное разделение составляет 50 мм." },
  "nia-08-004": { explanation: "Пересечение под прямым углом сводит к минимуму параллельное воздействие между кабелями и возникающие при этом электромагнитные помехи." },
  "nia-08-005": { explanation: "Люминесцентные светильники могут быть значительным источником ЭМИ. В качестве минимального расстояния в руководстве используется 130 мм." },
  "nia-08-006": { explanation: "Разделение защищает как производительность передачи данных, так и безопасность персонала, поскольку наведенное напряжение на телекоммуникационном кабеле может стать причиной поражения током." },
  "nia-08-007": { explanation: "Связь ЭМИ увеличивается с ростом тока в силовом кабеле и уменьшается с расстоянием от телекоммуникационного кабеля. Показатель 50 мм предполагает типичные условия." },
  "nia-08-008": { explanation: "Экранирование, металлическая изоляция и физическое разделение - все это снижает ЭМИ. Простой UTP сам по себе не является методом борьбы с ЭМИ." },
  "nia-08-009": { explanation: "HSG47 (\"Предотвращение опасности от подземных коммуникаций\") - это соответствующее руководство HSE." },
  "nia-08-010": { explanation: "Работа на высоте применяется только в тех случаях, когда существует риск падения (например, в глубоких котлованах). Обычные работы по обслуживанию грунта в основном связаны с CDM, PSR и правилами управления." },
  "nia-08-011": { explanation: "В камерах могут содержаться невидимые опасные газы. Перед входом в камеру необходимо провести проверку на наличие газов, часто в рамках процедуры проверки замкнутого пространства." },
  "nia-08-012": { explanation: "Желтый цвет ассоциируется с газом и не используется для воздуховодов телекоммуникаций. Белый, черный и серый - типичные цвета воздуховодов для телекоммуникаций." },
  "nia-08-013": { explanation: "Под пешеходной дорожкой согласно BS EN 50174-3, таблица 3, минимальная глубина должна составлять 500 мм." },
  "nia-08-014": { explanation: "Правильно скрепленная металлическая оболочка может служить экраном, снижая уровень электромагнитных помех вокруг кабелей." },
  "nia-08-015": { explanation: "Под дорогой или проезжей частью BS EN 50174-3 Таблица 3 устанавливает минимальную глубину 600 мм." },
  "nia-09-001": { explanation: "Политика управления отходами на объекте является обязательной и определяет маршрут утилизации каждого потока отходов." },
  "nia-09-002": { explanation: "Даже если картон выглядит пригодным для вторичной переработки, политика предприятия определяет правильный маршрут вывоза или сбора." },
  "nia-09-003": { explanation: "Отработанный кабель может быть пригоден для вторичной переработки или подлежит контракту с конкретным объектом. Способ утилизации определяется политикой." },
  "nia-09-004": { explanation: "Волокнистые осколки - это особый вид отходов. Их нельзя выбрасывать в контейнеры для общей или смешанной переработки." },
  "nia-09-005": { explanation: "Многие предприятия возвращают бочки поставщику для повторного использования или используют определенный способ утилизации. Не импровизируйте, выходя за рамки правил." },
  "nia-09-006": { explanation: "Медь - ценный материал, который можно извлечь. Политика предприятия обычно требует отделять медь в поток металлов, а не в общий скип." },
  "nia-09-007": { explanation: "Немаркированные контейнеры могут привести к перекрестному загрязнению отходов и неправильной утилизации. Перед использованием их необходимо идентифицировать." },
  "nia-09-008": { explanation: "Контейнеры, в которых хранились растворители или другие химические вещества, обычно классифицируются как опасные отходы, даже если они \"пустые\"." },
  "nia-09-009": { explanation: "Обрезки, оставленные в пустотах, увеличивают пожарную нагрузку и впоследствии могут быть приняты за проложенный кабель. Их необходимо извлечь и утилизировать надлежащим образом." },
  "nia-09-010": { explanation: "Иерархия отходов предписывает предприятиям в первую очередь предотвращать образование отходов, а утилизацию рассматривать как последний вариант. Это относится к упаковке, обрезкам и поврежденному инвентарю." },
  "nia-09-011": { explanation: "Повторное использование стоит выше переработки в иерархии отходов. Возврат поврежденных запасов в первую очередь предотвращает отходы." },
  "nia-09-012": { explanation: "В накладной на передачу отходов записываются данные об отходах, покидающих площадку. Стандартные поля включают описание, количество и стороны." },
  "nia-09-013": { explanation: "Правила WEEE распространяются на отходы электрического и электронного оборудования, включая активное сетевое оборудование, удаляемое во время ремонта." },
  "nia-09-014": { explanation: "Разливы растворителей требуют локализации и надлежащей утилизации загрязненного абсорбента. Сброс в канализацию обычно запрещен и может стать уголовным преступлением." },
  "nia-09-015": { explanation: "Предпочтительным результатом является повторное использование пригодных материалов. Утилизация пригодного к использованию материала является расточительством и может нарушить обязанности по уходу." },
};
